import { useState } from "react";
import Header from "./components/Header";
import "./App.css";

import { getWeather } from "./";
import logo from "./img/logoOne.png";
import sunImage from "./img/image.png";
import heroImage from "./img/Rectangle.png";

function App() {
  const [city, setCity] = useState("");
  const [weather, setWeather] = useState(null);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  async function handleSearch(event) {
    event.preventDefault();

    if (!city.trim()) {
      setError("Enter a city name");
      return;
    }

    setLoading(true);
    setError("");

    try {
      const data = await getWeather(city.trim());
      setWeather(data);
    } catch {
      setWeather(null);
      setError("City not found. Try another city.");
    } finally {
      setLoading(false);
    }
  }

  const temperature = weather
    ? `${Math.round(weather.main.temp)}°C`
    : "22°C";

  const cityName = weather?.name || "Prague";
  const country = weather?.sys?.country || "Czech Republic";

  return (
    <div className="app">
      <Header />

      <main>
        {/* БОЛЬШАЯ ФОТОГРАФИЯ: src/img/Rectangle.png */}
        <section
          className="hero"
          style={{ backgroundImage: `url(${heroImage})` }}
        >
          <h1>Weather dashboard</h1>

          <div className="hero__info">
            <p className="hero__description">
              Create your personal list of favorite cities and always be
              aware of the weather.
            </p>

            <div className="hero__date">
              <p>October 2023</p>
              <p>Friday, 13ᵗʰ</p>
            </div>
          </div>

          <form className="hero__search" onSubmit={handleSearch}>
            <input
              value={city}
              onChange={(event) => setCity(event.target.value)}
              placeholder="Search location..."
              aria-label="Search location"
            />
            <button type="submit" aria-label="Search">
              ⌕
            </button>
          </form>

          {loading && <p className="hero__message">Loading weather...</p>}
          {error && <p className="hero__message">{error}</p>}
        </section>

        {/* КАРТОЧКИ ПОГОДЫ: ИКОНКИ ПОГОДЫ ПОЛУЧАЕМ ИЗ API */}
        <section className="weather-cards">
          {[1, 2, 3].map((item) => (
            <article className="weather-card" key={item}>
              <div className="weather-card__cities">
                <span>{cityName}</span>
                <span>{country}</span>
              </div>

              <p className="weather-card__time">
                {weather
                  ? new Date(
                      (weather.dt + weather.timezone) * 1000
                    ).toISOString().slice(11, 16)
                  : "14:00"}
              </p>

              <p className="weather-card__day">
                {weather
                  ? new Date().toLocaleDateString("en-GB")
                  : "13.10.2023 | Friday"}
              </p>

              <span className="weather-card__label">
                {weather?.weather?.[0]?.description || "Mostly Sunny"}
              </span>

              {/* СОЛНЦЕ ПО УМОЛЧАНИЮ: src/img/image.png */}
              <img
                className="weather-card__sun"
                src={
                  weather?.weather?.[0]?.icon
                    ? `https://openweathermap.org/img/wn/${weather.weather[0].icon}@2x.png`
                    : sunImage
                }
                alt={weather?.weather?.[0]?.description || "Sunny weather"}
              />

              <p className="weather-card__temperature">{temperature}</p>

              <div className="weather-card__bottom">
                <button type="button" aria-label="Refresh">↻</button>
                <button type="button" aria-label="Add to favorites">♡</button>
                <button type="button" className="weather-card__more">
                  See more
                </button>
                <button type="button" aria-label="Delete">▣</button>
              </div>
            </article>
          ))}
        </section>

        {/* ДРУГИЕ СЕКЦИИ ДОБАВИМ ПОЗЖЕ */}

        {/* FOOTER */}
        <footer className="footer-container" id="contacts">
          <div className="footer__logo">
            <img src={logo} alt="24/7 Forecast" />
          </div>

          <div className="footer__address">
            <p>Address</p>
            <span>Svobody str. 35</span>
            <span>Kyiv</span>
            <span>Ukraine</span>
          </div>

          <div className="footer__social">
            <p>Contact us</p>
            <div className="footer__icons">
              <a href="#instagram" aria-label="Instagram">◎</a>
              <a href="#facebook" aria-label="Facebook">f</a>
              <a href="#whatsapp" aria-label="WhatsApp">◉</a>
            </div>
          </div>
        </footer>
      </main>
    </div>
  );
}

export default App;
